CREATE TABLE meta(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE users(id text PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,password text NOT NULL,role text NOT NULL CHECK(role IN ('admin','editor','viewer')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires bigint NOT NULL);
CREATE TABLE projects(id text PRIMARY KEY,name text NOT NULL,owner_id text NOT NULL REFERENCES users(id),visibility text NOT NULL CHECK(visibility IN ('team','private')),acl jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflows(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),name text NOT NULL,document jsonb NOT NULL,revision integer NOT NULL DEFAULT 1 CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chats(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),title text NOT NULL,messages jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets(id text PRIMARY KEY,project_id text REFERENCES projects(id),owner_id text NOT NULL REFERENCES users(id),name text NOT NULL,kind text NOT NULL,version integer NOT NULL DEFAULT 1,visibility text NOT NULL,acl jsonb NOT NULL DEFAULT '{}',mime text NOT NULL,file text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE models(id text PRIMARY KEY,name text NOT NULL,spec jsonb NOT NULL,secret text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skills(id text PRIMARY KEY,name text NOT NULL,task text NOT NULL,template text NOT NULL,builtin boolean NOT NULL DEFAULT false);
CREATE TABLE experts(id text PRIMARY KEY,name text NOT NULL,task text NOT NULL,skill_ids jsonb NOT NULL,builtin boolean NOT NULL DEFAULT false);
CREATE TABLE proposals(id text PRIMARY KEY,workflow_id text NOT NULL REFERENCES workflows(id),user_id text NOT NULL REFERENCES users(id),base_revision integer NOT NULL,document jsonb NOT NULL,explanation text NOT NULL,expires bigint NOT NULL,status text NOT NULL DEFAULT 'pending');
CREATE TABLE publications(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),workflow_id text NOT NULL REFERENCES workflows(id),owner_id text NOT NULL REFERENCES users(id),name text NOT NULL,version text NOT NULL,document jsonb NOT NULL,key_hash text UNIQUE NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),owner_id text NOT NULL REFERENCES users(id),source text NOT NULL,source_id text NOT NULL,publication_id text REFERENCES publications(id),snapshot jsonb NOT NULL,status text NOT NULL CHECK(status IN ('queued','running','completed','failed')),steps jsonb NOT NULL DEFAULT '{}',outputs jsonb NOT NULL DEFAULT '[]',error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_versions(workflow_id text NOT NULL REFERENCES workflows(id),revision integer NOT NULL,document jsonb NOT NULL,actor_id text REFERENCES users(id),action text NOT NULL,source_revision integer,saved_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workflow_id,revision));
CREATE TABLE workflow_templates(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),owner_id text NOT NULL REFERENCES users(id),name text NOT NULL,description text NOT NULL DEFAULT '',document jsonb NOT NULL,source_workflow_id text REFERENCES workflows(id),source_revision integer,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_test_cases(project_id text NOT NULL REFERENCES projects(id),test_id text NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(project_id,test_id));
CREATE TABLE request_keys(owner_id text NOT NULL REFERENCES users(id),scope text NOT NULL,key_hash text NOT NULL,request_hash text NOT NULL,job_id text NOT NULL REFERENCES jobs(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,scope,key_hash));
CREATE INDEX jobs_source ON jobs(source_id,created_at DESC);
CREATE INDEX jobs_pending ON jobs(status,created_at);
CREATE INDEX assets_project ON assets(project_id);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX workflow_templates_project ON workflow_templates(project_id);
